<?php
namespace App\Services\Excel\Imports;
use App\Models\PaymentStage; use App\Models\Project; use App\Services\Excel\ExcelImportDefinition; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator;
class PaymentStageImport implements ExcelImportDefinition {
 public function module(): string{return 'payment_stages';} public function requiredHeaders():array{return ['name'];}
 public function importRow(array $row,int $rowNumber):string { $name=trim((string)($row['name']??'')); $v=Validator::make(['name'=>$name],['name'=>'required|string|max:255']); if($v->fails())throw new \InvalidArgumentException('Validation failed: '.implode(' ',$v->errors()->all())); $project=Project::query()->first(); if(!$project)throw new \InvalidArgumentException('No project is available for this payment stage.'); $column=\Schema::hasColumn('payment_stages','stage_name')?'stage_name':'name'; $existing=PaymentStage::where($column,$name)->where('project_id',$project->id)->first(); $wasNew=!$existing; $data=[$column=>$name,'project_id'=>$project->id]; foreach(['percentage'=>0,'status'=>'pending','order'=>(int)PaymentStage::max('order')+1] as $k=>$val)if(\Schema::hasColumn('payment_stages',$k))$data[$k]=$val; DB::transaction(function()use(&$existing,$data){ if($existing){ DB::table('payment_stages')->where('id',$existing->id)->update(array_merge($data,['updated_at'=>now()])); } else { $id=DB::table('payment_stages')->insertGetId(array_merge($data,['created_at'=>now(),'updated_at'=>now()])); $existing=PaymentStage::find($id); } }); return $wasNew?'created':'updated'; }
}
